// Guard the boundary with the outside world.
//
// The HTTP node already fails on a non-2xx status and on a network error. What
// it cannot judge is whether a 200 response is actually the payload we expect,
// so that check lives here. Throwing stops the workflow: a malformed response
// must never be treated as "zero orders today" and quietly close the run as a
// success.

const batch = $('Create Batch Context').first().json;
const body = $input.first().json;

if (body === null || typeof body !== 'object') {
  throw new Error(`Mock API returned a ${typeof body} rather than a JSON object`);
}

if (!Array.isArray(body.orders)) {
  throw new Error(
    `Mock API response has no "orders" array (got ${typeof body.orders}). ` +
    `Keys present: ${Object.keys(body).join(', ') || '<none>'}`
  );
}

if (typeof body.count !== 'number') {
  throw new Error('Mock API response has no numeric "count" field');
}

// A self-inconsistent response means truncation or a contract change upstream.
// Either way, ingesting it would silently under-count revenue.
if (body.count !== body.orders.length) {
  throw new Error(
    `Mock API response is inconsistent: count=${body.count} but ` +
    `orders array holds ${body.orders.length} items`
  );
}

// An empty window is legitimate - a re-run within the same hour, or a window
// with no trading. It is not an error; it flows through as a run of zero.
return [{
  json: {
    batch_id: batch.batch_id,
    window_from: batch.window_from,
    window_to: batch.window_to,
    records_received: body.orders.length,
    orders_json: JSON.stringify(body.orders),
  },
}];
